import React, { useState, useEffect } from 'react';
import { MapContainer, TileLayer, Marker, Popup, Circle } from 'react-leaflet';
import axios from 'axios';
import io from 'socket.io-client';
import 'leaflet/dist/leaflet.css';
import L from 'leaflet';

// Fix for default marker icon
delete L.Icon.Default.prototype._getIconUrl;
L.Icon.Default.mergeOptions({
  iconRetinaUrl: require('leaflet/dist/images/marker-icon-2x.png'),
  iconUrl: require('leaflet/dist/images/marker-icon.png'),
  shadowUrl: require('leaflet/dist/images/marker-shadow.png'),
});

const API_URL = 'http://localhost:5000/api';
const SOCKET_URL = 'http://localhost:5000';

// Adventure Tourism & Popular Locations
const LOCATIONS = [
  // Tamil Nadu Adventure Spots
  { name: '🏔️ Ooty Hill Station (Nilgiris)', lat: 11.4102, lng: 76.6950 },
  { name: '🌲 Doddabetta Peak Trek (Ooty)', lat: 11.4064, lng: 76.7337 },
  { name: '🏞️ Kodaikanal Hills (Tamil Nadu)', lat: 10.2381, lng: 77.4892 },
  { name: '🌳 Valparai Forest (Western Ghats)', lat: 10.3270, lng: 76.9550 },
  { name: '⛰️ Yercaud Hills (Salem)', lat: 11.7776, lng: 78.2046 },
  { name: '🏕️ Topslip Forest (Anamalai)', lat: 10.3583, lng: 76.8833 },
  { name: '🌲 Marudhamalai Forest (Coimbatore)', lat: 11.0450, lng: 76.8700 },
  { name: '🏙️ Coimbatore City, Tamil Nadu', lat: 11.0168, lng: 76.9558 },
  { name: '🏙️ Chennai, Tamil Nadu', lat: 13.0827, lng: 80.2707 },
  { name: '🕌 Madurai, Tamil Nadu', lat: 9.9252, lng: 78.1198 },

  // India Adventure Destinations
  { name: '🏔️ Manali (Himachal Pradesh)', lat: 32.2432, lng: 77.1892 },
  { name: '⛰️ Leh-Ladakh (Jammu & Kashmir)', lat: 34.1526, lng: 77.5771 },
  { name: '🌲 Jim Corbett National Park', lat: 29.5308, lng: 78.7739 },
  { name: '🏞️ Rishikesh (Uttarakhand)', lat: 30.0869, lng: 78.2676 },
  { name: '🏕️ Coorg (Karnataka)', lat: 12.3375, lng: 75.8069 },
  { name: '🌳 Munnar Hills (Kerala)', lat: 10.0889, lng: 77.0595 },

  // Major Cities
  { name: '🏙️ New Delhi, India', lat: 28.6139, lng: 77.2090 },
  { name: '🏙️ Mumbai, India', lat: 19.0760, lng: 72.8777 },
  { name: '🏙️ Bangalore, India', lat: 12.9716, lng: 77.5946 },

  // International Adventure Spots
  { name: '🏔️ Swiss Alps (Switzerland)', lat: 46.5197, lng: 8.3093 },
  { name: '⛰️ Mount Fuji (Japan)', lat: 35.3606, lng: 138.7274 },
  { name: '🌲 Amazon Rainforest (Brazil)', lat: -3.4653, lng: -62.2159 },
  { name: '🏞️ Grand Canyon (USA)', lat: 36.1069, lng: -112.1129 },
  { name: '🏕️ Yellowstone Park (USA)', lat: 44.4280, lng: -110.5885 },

  // Restricted/Dangerous Areas (from global database)
  { name: '🚨 Mount Everest Base Camp (Nepal)', lat: 28.0026, lng: 86.8528 },
  { name: '☢️ Chernobyl Exclusion Zone (Ukraine)', lat: 51.3890, lng: 30.0990 },
  { name: '🚫 North Sentinel Island (India)', lat: 11.5570, lng: 92.2410 },
  { name: '🚫 Area 51 (USA)', lat: 37.2350, lng: -115.8111 },
  { name: '☢️ Fukushima Exclusion Zone (Japan)', lat: 37.4213, lng: 141.0327 },
  { name: '🐍 Snake Island (Brazil)', lat: -24.4858, lng: -46.6769 },

  // International Cities
  { name: '🏙️ Paris, France', lat: 48.8566, lng: 2.3522 },
  { name: '🏙️ London, UK', lat: 51.5074, lng: -0.1278 },
  { name: '🏙️ New York, USA', lat: 40.7128, lng: -74.0060 },
  { name: '🏙️ Tokyo, Japan', lat: 35.6762, lng: 139.6503 },
  { name: '🏙️ Dubai, UAE', lat: 25.2048, lng: 55.2708 },
  { name: '🏙️ Singapore', lat: 1.3521, lng: 103.8198 },
  { name: '🏙️ Sydney, Australia', lat: -33.8688, lng: 151.2093 }
];

function TouristDashboard({ onLogout }) {
  const [userData, setUserData] = useState(null);
  const [location, setLocation] = useState({ lat: 11.4102, lng: 76.6950 }); // Default: Ooty
  const [selectedCity, setSelectedCity] = useState('🏔️ Ooty Hill Station (Nilgiris)');
  const [safeZones, setSafeZones] = useState([]);
  const [incidents, setIncidents] = useState([]);
  const [safetyStatus, setSafetyStatus] = useState('safe');
  const [socket, setSocket] = useState(null);

  useEffect(() => {
    const data = JSON.parse(localStorage.getItem('userData'));
    setUserData(data);

    fetchSafeZones();
    fetchIncidents();

    // Initialize socket connection
    const newSocket = io(SOCKET_URL);
    setSocket(newSocket);

    return () => newSocket.close();
  }, []);

  const fetchSafeZones = async () => {
    try {
      const token = localStorage.getItem('token');
      const response = await axios.get(`${API_URL}/admin/safezones`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setSafeZones(response.data);
    } catch (error) {
      console.error('Error fetching safe zones:', error);
    }
  };

  const fetchIncidents = async () => {
    try {
      const token = localStorage.getItem('token');
      const response = await axios.get(`${API_URL}/tourist/incidents`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setIncidents(response.data);
    } catch (error) {
      console.error('Error fetching incidents:', error);
    }
  };

  const playAlertSound = () => {
    // Create audio context for continuous 10-second beep
    const audioContext = new (window.AudioContext || window.webkitAudioContext)();
    const oscillator = audioContext.createOscillator();
    const gainNode = audioContext.createGain();

    oscillator.connect(gainNode);
    gainNode.connect(audioContext.destination);

    // Set frequency for alarm sound
    oscillator.frequency.value = 800;
    oscillator.type = 'sine';

    // Set volume
    gainNode.gain.setValueAtTime(0.3, audioContext.currentTime);

    // Play continuous beep for 10 seconds
    oscillator.start(audioContext.currentTime);
    oscillator.stop(audioContext.currentTime + 10);
  };

  const updateLocation = async (lat, lng) => {
    try {
      const token = localStorage.getItem('token');
      const response = await axios.post(
        `${API_URL}/tourist/location`,
        { lat, lng },
        { headers: { Authorization: `Bearer ${token}` } }
      );

      setLocation({ lat, lng });
      setSafetyStatus(response.data.safetyStatus);

      // Emit location update via socket
      if (socket) {
        socket.emit('locationUpdate', {
          touristId: userData.id,
          location: { lat, lng },
          status: response.data.safetyStatus
        });
      }

      // Handle restricted area alert
      if (response.data.playAlert && response.data.restrictedArea) {
        playAlertSound();
        const area = response.data.restrictedArea;
        alert(
          `🚨 RESTRICTED AREA ALERT 🚨\n\n` +
          `Location: ${area.name}, ${area.country}\n` +
          `Restriction: ${area.restriction_type}\n` +
          `Reason: ${area.restriction_reason}\n` +
          `Level: ${area.restriction_level}\n` +
          `Status: ${area.restriction_status}\n` +
          `Distance: ${area.distance}m from center\n\n` +
          `⚠️ Admin has been notified via SMS\n` +
          `📝 Incident recorded on blockchain\n` +
          `🔗 TX Hash: ${response.data.blockchainTxHash?.substring(0, 20)}...\n\n` +
          `Source: ${area.official_source}`
        );
      } else if (!response.data.isInSafeZone) {
        playAlertSound();
        alert('⚠️ WARNING: You are outside the safe zone!');
      } else {
        alert('✅ You are in a safe zone');
      }

      fetchIncidents();
    } catch (error) {
      console.error('Error updating location:', error);
      alert('Error updating location. Check if backend is running.');
    }
  };

  const simulateMovement = () => {
    // Simulate random movement
    const newLat = location.lat + (Math.random() - 0.5) * 0.01;
    const newLng = location.lng + (Math.random() - 0.5) * 0.01;
    updateLocation(newLat, newLng);
  };

  const moveToSafeZone = () => {
    if (safeZones.length > 0) {
      const zone = safeZones[0];
      updateLocation(zone.center.lat, zone.center.lng);
    } else {
      alert('No safe zones created yet! Ask admin to create a safe zone first.');
    }
  };

  const moveOutsideSafeZone = () => {
    if (safeZones.length > 0) {
      const zone = safeZones[0];
      // Move 6km away from safe zone center
      updateLocation(zone.center.lat + 0.06, zone.center.lng + 0.06);
    } else {
      alert('No safe zones created yet! Ask admin to create a safe zone first.');
    }
  };

  const handleCityChange = (e) => {
    const cityName = e.target.value;
    setSelectedCity(cityName);
    const city = LOCATIONS.find(loc => loc.name === cityName);
    if (city) {
      setLocation({ lat: city.lat, lng: city.lng });
      updateLocation(city.lat, city.lng);
    }
  };

  return (
    <div>
      <div className="navbar">
        <h1>Tourist Dashboard</h1>
        <div>
          <span style={{ marginRight: '20px' }}>Welcome, {userData?.name}</span>
          <button onClick={onLogout}>Logout</button>
        </div>
      </div>

      <div className="container">
        <div className="card">
          <h3>Safety Status</h3>
          <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
            <span className={`status-badge status-${safetyStatus}`}>
              {safetyStatus.toUpperCase()}
            </span>
            <span>Wallet: {userData?.walletAddress?.substring(0, 10)}...</span>
          </div>
        </div>

        <div className="card">
          <h3>Location Tracking</h3>

          <div className="form-group">
            <label>Select City/Location:</label>
            <select 
              value={selectedCity} 
              onChange={handleCityChange}
              style={{ 
                width: '100%', 
                padding: '10px', 
                border: '1px solid #ddd', 
                borderRadius: '5px',
                fontSize: '16px'
              }}
            >
              {LOCATIONS.map((loc) => (
                <option key={loc.name} value={loc.name}>
                  {loc.name}
                </option>
              ))}
            </select>
          </div>

          <p>Current Location: {location.lat.toFixed(4)}, {location.lng.toFixed(4)}</p>

          <div style={{ marginBottom: '20px', display: 'flex', gap: '10px', flexWrap: 'wrap' }}>
            <button onClick={simulateMovement} className="btn btn-primary">
              Simulate Movement
            </button>
            <button onClick={moveToSafeZone} className="btn btn-success">
              Move to Safe Zone
            </button>
            <button onClick={moveOutsideSafeZone} className="btn btn-danger">
              Move Outside (Test Alert)
            </button>
          </div>

          <MapContainer center={[location.lat, location.lng]} zoom={13} style={{ height: '400px' }} key={`${location.lat}-${location.lng}`}>
            <TileLayer
              url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
              attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>'
            />

            {/* Tourist marker */}
            <Marker position={[location.lat, location.lng]}>
              <Popup>Your Location</Popup>
            </Marker>

            {/* Safe zones */}
            {safeZones.map((zone) => (
              <Circle
                key={zone._id}
                center={[zone.center.lat, zone.center.lng]}
                radius={zone.radius}
                pathOptions={{ color: 'green', fillColor: 'green', fillOpacity: 0.2 }}
              >
                <Popup>{zone.name}</Popup>
              </Circle>
            ))}
          </MapContainer>
        </div>

        <div className="card">
          <h3>Safe & Restricted Zones</h3>
          {safeZones.length === 0 ? (
            <p>No zones created yet. Admin needs to create safe zones.</p>
          ) : (
            <div>
              <h4 style={{ color: '#28a745', marginBottom: '10px' }}>✅ Safe Zones ({safeZones.filter(z => z.isActive).length})</h4>
              {safeZones.filter(z => z.isActive).map((zone) => (
                <div key={zone._id} style={{ 
                  padding: '10px', 
                  marginBottom: '10px', 
                  background: '#d4edda', 
                  borderRadius: '5px',
                  border: '1px solid #c3e6cb'
                }}>
                  <strong>{zone.name}</strong>
                  <p style={{ margin: '5px 0', fontSize: '14px' }}>
                    📍 Location: {zone.center.lat.toFixed(4)}, {zone.center.lng.toFixed(4)}
                  </p>
                  <p style={{ margin: '5px 0', fontSize: '14px' }}>
                    🔵 Radius: {zone.radius}m ({(zone.radius/1000).toFixed(1)}km)
                  </p>
                  <p style={{ margin: '5px 0', fontSize: '14px', color: '#155724' }}>
                    ✅ Status: Safe to visit
                  </p>
                </div>
              ))}

              <h4 style={{ color: '#dc3545', marginTop: '20px', marginBottom: '10px' }}>🚨 Restricted/Dangerous Areas</h4>
              <div style={{ 
                padding: '10px', 
                background: '#f8d7da', 
                borderRadius: '5px',
                border: '1px solid #f5c6cb'
              }}>
                <p style={{ margin: '5px 0', fontSize: '14px', color: '#721c24' }}>
                  ⚠️ Government-restricted areas are marked with 🚨, ☢️, 🚫, 🐍 in dropdown
                </p>
                <p style={{ margin: '5px 0', fontSize: '14px', color: '#721c24' }}>
                  🔴 Entering restricted zones triggers: 2-second beep + SMS to admin + blockchain record
                </p>
                <p style={{ margin: '5px 0', fontSize: '14px', color: '#721c24' }}>
                  📝 Examples: Chernobyl, Area 51, North Sentinel Island, Fukushima, Snake Island
                </p>
                <p style={{ margin: '5px 0', fontSize: '14px', color: '#721c24' }}>
                  📱 All restrictions verified from official government/UNESCO sources
                </p>
              </div>
            </div>
          )}
        </div>

        <div className="card">
          <h3>Incident History (Blockchain)</h3>
          {incidents.length === 0 ? (
            <p>No incidents recorded</p>
          ) : (
            <div style={{ maxHeight: '300px', overflowY: 'auto' }}>
              {incidents.map((incident) => (
                <div key={incident.id} className="alert alert-warning" style={{ marginBottom: '10px' }}>
                  <strong>Incident #{incident.id}</strong>
                  <p>Type: {incident.incidentType}</p>
                  <p>Location: {incident.location}</p>
                  <p>Time: {new Date(Number(incident.timestamp) * 1000).toLocaleString()}</p>
                  <p>Status: {incident.resolved ? 'Resolved' : 'Pending'}</p>
                  <p>Description: {incident.description}</p>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

export default TouristDashboard;
